#!/bin/bash
# 🍄 MUSHROOM: manifest auto-regen
# Scans all data files and regenerates manifest.json
# The manifest IS the organism's self-knowledge

cd /home/eastgate/Development/ecoPrimals/infra/hud/site/public/data

python3 -c "
import json, glob, os, time, hashlib

ts = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
files = sorted(glob.glob('*.json'))
manifest = {
    'ts': ts,
    'type': 'manifest',
    'title': 'Data Manifest — auto-regenerated by mushroom mycelium',
    'total_files': len(files),
    'total_bytes': sum(os.path.getsize(f) for f in files if os.path.isfile(f)),
    'files': []
}

for f in files:
    if f == 'manifest.json': continue
    try:
        size = os.path.getsize(f)
        mtime = os.path.getmtime(f)
        age_h = (time.time() - mtime) / 3600
        d = json.load(open(f))
        title = d.get('title', f)[:80] if isinstance(d, dict) else f
        manifest['files'].append({
            'file': f,
            'size': size,
            'age_hours': round(age_h, 1),
            'title': title
        })
    except: pass

h = hashlib.blake2b(json.dumps(manifest, sort_keys=True).encode(), digest_size=16).hexdigest()
manifest['hash'] = h
json.dump(manifest, open('manifest.json', 'w'), indent=2, ensure_ascii=False)
"

